        try c.encode(self.overriddenToday, forKey: .overriddenToday)
        try c.encode(self.blocked, forKey: .blocked)
        try c.encode(self.alertsToday, forKey: .alertsToday)
    }
}

public struct WeeklyPaceAlertsToday: Codable, Hashable, Sendable {
    public let soft: String?
    public let hard: String?

    public init(soft: String? = nil, hard: String? = nil) {
        self.soft = soft
        self.hard = hard
    }

    private enum CodingKeys: String, CodingKey {
        case soft
        case hard
    }

    public init(from decoder: Decoder) throws {
        let c = try decoder.container(keyedBy: CodingKeys.self)
        self.soft = try c.decodeIfPresent(String.self, forKey: .soft)
        self.hard = try c.decodeIfPresent(String.self, forKey: .hard)
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.container(keyedBy: CodingKeys.self)
        try c.encode(self.soft, forKey: .soft)
        try c.encode(self.hard, forKey: .hard)
    }
}

/// Noma'lum (kelajakdagi) qiymatlar `.unknown(raw)` bo'lib dekodlanadi, xato tashlanmaydi.
public enum WeeklyPaceSource: Hashable, Sendable, Codable {
    case official
    case estimate
    case unknown(String)

    public init(rawValue: String) {
        switch rawValue {
        case "official": self = .official
        case "estimate": self = .estimate
        default: self = .unknown(rawValue)
        }
    }

    public var rawValue: String {
        switch self {
        case .official: return "official"
        case .estimate: return "estimate"
        case .unknown(let raw): return raw
        }
    }

    public init(from decoder: Decoder) throws {
        self.init(rawValue: try decoder.singleValueContainer().decode(String.self))
    }

    public func encode(to encoder: Encoder) throws {
        var c = encoder.singleValueContainer()
        try c.encode(rawValue)
    }
}
